</script>
<template>
<div>
<div id="map-container" />
<UILayer v-if="isLoaded" />
</div>
</template>
<style scoped>
#map-container {
position: absolute;
top: 0; bottom: 0;
left: 0; right: 0;
background: #022B4F;
}
</style>
<!-- App.vue -->
<script setup lang="ts">
import Map from './Map.vue'
</script>
